import{_ as i,a0 as l,w as p,s as r,I as e,x as a,a1 as n,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何使用 autofs 挂载 NFS 共享 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 autofs 挂载 NFS 共享 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 autofs 挂载 NFS 共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 autofs 挂载 NFS 共享 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20180605 How to use autofs to mount NFS shares","title":"如何使用 autofs 挂载 NFS 共享","tag":"201905","desc":""},"relativePath":"201905/20180605 How to use autofs to mount NFS shares.md","filePath":"[post].md"}'),u={name:"201905/20180605 How to use autofs to mount NFS shares.md"};function c(h,s,g,k,f,m){const t=l("Link");return p(),r("div",null,[s[20]||(s[20]=e("h1",{id:"如何使用-autofs-挂载-nfs-共享",tabindex:"-1"},[a("如何使用 autofs 挂载 NFS 共享 "),e("a",{class:"header-anchor",href:"#如何使用-autofs-挂载-nfs-共享","aria-label":"Permalink to “如何使用 autofs 挂载 NFS 共享”"},"​")],-1)),s[21]||(s[21]=e("blockquote",null,[e("p",null,"给你的网络文件系统（NFS）配置一个基本的自动挂载功能。")],-1)),s[22]||(s[22]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/201905/08/115328rva7kqw9wqh2qees.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("大多数 Linux 文件系统在引导时挂载，并在系统运行时保持挂载状态。对于已在 ",-1)),s[2]||(s[2]=e("code",null,"fstab",-1)),s[3]||(s[3]=a(" 中配置的任何远程文件系统也是如此。但是，有时你可能希望仅按需挂载远程文件系统。例如，通过减少网络带宽使用来提高性能，或出于安全原因隐藏或混淆某些目录。",-1)),n(t,{href:"https://wiki.archlinux.org/index.php/autofs"},{default:o(()=>[...s[0]||(s[0]=[a("autofs",-1)])]),_:1}),s[4]||(s[4]=a(" 软件包提供此功能。在本文中，我将介绍如何配置基本的自动挂载。",-1))]),s[23]||(s[23]=d(`<p>首先做点假设：假设有台 NFS 服务器 <code>tree.mydatacenter.net</code> 已经启动并运行。另外假设一个名为 <code>ourfiles</code> 的数据目录还有供 Carl 和 Sarah 使用的用户目录，它们都由服务器共享。</p><p>一些最佳实践可以使工作更好：服务器上的用户和任何客户端工作站上的帐号有相同的用户 ID。此外，你的工作站和服务器应有相同的域名。检查相关配置文件应该确认。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:~$ sudo getent passwd carl sarah</span></span>
<span class="line"><span>[sudo] password for alan:</span></span>
<span class="line"><span>carl:x:1020:1020:Carl,,,:/home/carl:/bin/bash</span></span>
<span class="line"><span>sarah:x:1021:1021:Sarah,,,:/home/sarah:/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation1:~$ sudo getent hosts</span></span>
<span class="line"><span>127.0.0.1       localhost</span></span>
<span class="line"><span>127.0.1.1       workstation1.mydatacenter.net workstation1</span></span>
<span class="line"><span>10.10.1.5       tree.mydatacenter.net tree</span></span></code></pre></div><p>如你所见，客户端工作站和 NFS 服务器都在 <code>hosts</code> 文件中配置。我假设这是一个基本的家庭甚至小型办公室网络，可能缺乏适合的内部域名服务（即 DNS）。</p><h3 id="安装软件包" tabindex="-1">安装软件包 <a class="header-anchor" href="#安装软件包" aria-label="Permalink to “安装软件包”">​</a></h3><p>你只需要安装两个软件包：用于 NFS 客户端的 <code>nfs-common</code> 和提供自动挂载的 <code>autofs</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:~$ sudo apt-get install nfs-common autofs</span></span></code></pre></div><p>你可以验证 autofs 相关的文件是否已放在 <code>/etc</code> 目录中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:~$ cd /etc; ll auto*</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 12596 Nov 19  2015 autofs.conf</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   857 Mar 10  2017 auto.master</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   708 Jul  6  2017 auto.misc</span></span>
<span class="line"><span>-rwxr-xr-x 1 root root  1039 Nov 19  2015 auto.net*</span></span>
<span class="line"><span>-rwxr-xr-x 1 root root  2191 Nov 19  2015 auto.smb*</span></span>
<span class="line"><span>alan@workstation1:/etc$</span></span></code></pre></div><h3 id="配置-autofs" tabindex="-1">配置 autofs <a class="header-anchor" href="#配置-autofs" aria-label="Permalink to “配置 autofs”">​</a></h3><p>现在你需要编辑其中几个文件并添加 <code>auto.home</code> 文件。首先，将以下两行添加到文件 <code>auto.master</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/mnt/tree  /etc/auto.misc</span></span>
<span class="line"><span>/home/tree  /etc/auto.home</span></span></code></pre></div><p>每行以挂载 NFS 共享的目录开头。继续创建这些目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:/etc$ sudo mkdir /mnt/tree /home/tree</span></span></code></pre></div><p>接下来，将以下行添加到文件 <code>auto.misc</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ourfiles        -fstype=nfs     tree:/share/ourfiles</span></span></code></pre></div><p>该行表示 autofs 将挂载 <code>auto.master</code> 文件中匹配 <code>auto.misc</code> 的 <code>ourfiles</code> 共享。如上所示，这些文件将在 <code>/mnt/tree/ourfiles</code> 目录中。</p><p>第三步，使用以下行创建文件 <code>auto.home</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*               -fstype=nfs     tree:/home/&amp;</span></span></code></pre></div><p>该行表示 autofs 将挂载 <code>auto.master</code> 文件中匹配 <code>auto.home</code> 的用户共享。在这种情况下，Carl 和 Sarah 的文件将分别在目录 <code>/home/tree/carl</code> 或 <code>/home/tree/sarah</code>中。星号 <code>*</code>（称为通配符）使每个用户的共享可以在登录时自动挂载。<code>＆</code> 符号也可以作为表示服务器端用户目录的通配符。它们的主目录会相应地根据 <code>passwd</code> 文件映射。如果你更喜欢本地主目录，则无需执行此操作。相反，用户可以将其用作特定文件的简单远程存储。</p><p>最后，重启 <code>autofs</code> 守护进程，以便识别并加载这些配置的更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:/etc$ sudo service autofs restart</span></span></code></pre></div><h3 id="测试-autofs" tabindex="-1">测试 autofs <a class="header-anchor" href="#测试-autofs" aria-label="Permalink to “测试 autofs”">​</a></h3><p>如果更改文件 <code>auto.master</code> 中的列出目录，并运行 <code>ls</code> 命令，那么不会立即看到任何内容。例如，切换到目录 <code>/mnt/tree</code>。首先，<code>ls</code> 的输出不会显示任何内容，但在运行 <code>cd ourfiles</code> 之后，将自动挂载 <code>ourfiles</code> 共享目录。 <code>cd</code> 命令也将被执行，你将进入新挂载的目录中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>carl@workstation1:~$ cd /mnt/tree</span></span>
<span class="line"><span>carl@workstation1:/mnt/tree$ ls</span></span>
<span class="line"><span>carl@workstation1:/mnt/tree$ cd ourfiles</span></span>
<span class="line"><span>carl@workstation1:/mnt/tree/ourfiles$</span></span></code></pre></div><p>为了进一步确认正常工作，<code>mount</code> 命令会显示已挂载共享的细节。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>carl@workstation1:~$ mount</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tree:/mnt/share/ourfiles on /mnt/tree/ourfiles type nfs4 (rw,relatime,vers=4.0,rsize=131072,wsize=131072,namlen=255,hard,proto=tcp,timeo=600,retrans=2,sec=sys,clientaddr=10.10.1.22,local_lock=none,addr=10.10.1.5)</span></span></code></pre></div><p>对于 Carl 和 Sarah，<code>/home/tree</code> 目录工作方式相同。</p><p>我发现在我的文件管理器中添加这些目录的书签很有用，可以用来快速访问。</p><hr>`,30)),e("p",null,[s[6]||(s[6]=a("via: ",-1)),n(t,{href:"https://opensource.com/article/18/6/using-autofs-mount-nfs-shares"},{default:o(()=>[...s[5]||(s[5]=[a("https://opensource.com/article/18/6/using-autofs-mount-nfs-shares",-1)])]),_:1})]),e("p",null,[s[11]||(s[11]=a("作者：",-1)),n(t,{href:"https://opensource.com/users/alanfdoss"},{default:o(()=>[...s[7]||(s[7]=[a("Alan Formy-Duval",-1)])]),_:1}),s[12]||(s[12]=a(" 选题：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:o(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:o(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const x=i(u,[["render",c]]);export{C as __pageData,x as default};
